// Takes hours, hourly rate, and a boolean isWeekend
// First 40 hours at regular rate, overtime at 1.5x
// Weekend multiplies total pay by 1.5
// Returns the total pay

function calculatePay(hours, rate, isWeekend) {

}

exercises.solution:
function calculatePay(hours, rate, isWeekend) {
  let pay;
  if (hours <= 40) {
    pay = hours * rate;
  } else {
    pay = 40 * rate + (hours - 40) * rate * 1.5;
