// Build an n×n multiplication table as a 2D array
// Cell [i][j] = (i + 1) * (j + 1)
function multiplicationTable(n) {

}

exercises.solution:
function multiplicationTable(n) {
  const table = [];
  for (let i = 0; i < n; i++) {
    const row = [];
    for (let j = 0; j < n; j++) {
      row.push((i + 1) * (j + 1));
    }
    table.push(row);
  }
  return table;
}

