exercises.starterCode:
// The `break` statement exits a loop immediately.
// Use it to stop searching once you find what you need.
//
// Syntax:
//   for (...) {
//     if (condition) {
//       break; // exits the loop right here
//     }
//   }

// Return the index of the first occurrence of target, or -1
function findFirst(arr, target) {
  // Create a variable to store the result index (-1 by default)
  // Loop through the array
  //   If the current element matches target:
  //     Save the index and break out of the loop
  // Return the result
}

exercises.solution:
function findFirst(arr, target) {
  let index = -1;
  for (let i = 0; i < arr.length; i++) {
    if (arr[i] === target) {
      index = i;
      break;
    }
  }
  return index;
}

