exercises.solution:
function hasValue(grid, target) {
  let found = false;
  for (let i = 0; i < grid.length; i++) {
    for (let j = 0; j < grid[i].length; j++) {
      if (grid[i][j] === target) {
        found = true;
        break;
      }
    }
    if (found) {
      break;
    }
  }
  return found;
}

