exercises.starterCode:
// do...while executes the body FIRST, then checks the condition.
// This guarantees at least one iteration.
//
// Syntax:
//   do {
//     // runs at least once
//   } while (condition);
//
// Use this when you need to process before checking.

// Sum the digits of a non-negative integer
function digitSum(n) {
  // Create a sum variable
  // do:
  //   Add the last digit (n % 10) to sum
  //   Remove the last digit (Math.floor(n / 10))
  // while n is greater than 0
  // Return sum
}

exercises.solution:
function digitSum(n) {
  let sum = 0;
  do {
    sum += n % 10;
    n = Math.floor(n / 10);
  } while (n > 0);
  return sum;
}

