exercises.starterCode:
// Combine for...of, continue, break, and .trim()
// to collect valid names from the array

// Return trimmed valid names, skip blanks, stop at "STOP"
function collectValidNames(entries) {

}

exercises.solution:
function collectValidNames(entries) {
  const names = [];
  for (const entry of entries) {
    if (entry.trim() === 'STOP') {
      break;
    }
    if (entry.trim() === '') {
      continue;
    }
    names.push(entry.trim());
  }
  return names;
}

