function wordFrequency(text) {
  if (text === '') return {};
  const words = text.split(' ');
  const freq = {};
  for (let i = 0; i < words.length; i++) {
    const word = words[i].toLowerCase();
    if (freq[word] === undefined) {
      freq[word] = 1;
    } else {
      freq[word]++;
    }
  }
  return freq;
}

