exercises.solution:
function sortAlphabetical(words) {
  return words.slice().sort(function(a, b) {
    var lowerA = a.toLowerCase();
    var lowerB = b.toLowerCase();
    if (lowerA < lowerB) return -1;
    if (lowerA > lowerB) return 1;
    return 0;
  });
}

