exercises.solution:
function sortMultiKey(students) {
  return students.slice().sort(function(a, b) {
    if (a.grade !== b.grade) return b.grade - a.grade;
    if (a.name < b.name) return -1;
    if (a.name > b.name) return 1;
    return 0;
  });
}

