exercises.starterCode:
/**
 * Compose any number of single-argument functions, applied right-to-left.
 * composeAll(f, g, h)(x) equals f(g(h(x)))
 *
 * @param {...Function} fns - Functions to compose (at least one)
 * @returns {Function} A function that applies all fns right-to-left
 */
function composeAll() {
  var fns = [];
  for (var i = 0; i < arguments.length; i++) {
    fns.push(arguments[i]);
  }

}

exercises.solution:
function composeAll() {
