/**
 * @returns {{ add: Function, subtract: Function, getResult: Function, getHistory: Function }}
 *   add(n) - adds n to result, records "add:n" in history
 *   subtract(n) - subtracts n from result, records "subtract:n" in history
 *   getResult() - returns current result (starts at 0)
 *   getHistory() - returns copy of the operations history array
 */
function createCalculator() {

}

exercises.solution:
function createCalculator() {
  var result = 0;
  var history = [];

  function add(n) {
    result += n;
    history.push("add:" + n);
  }

  function subtract(n) {
    result -= n;
    history.push("subtract:" + n);
  }

  function getResult() {
    return result;
  }

  function getHistory() {
    return history.slice();
  }

  return {
    add: add,
    subtract: subtract,
    getResult: getResult,
    getHistory: getHistory
  };
}

