exercises.solution:
class MathHelper {
  static clamp(n, min, max) {
    if (n < min) return min;
    if (n > max) return max;
    return n;
  }

  static average(...nums) {
    if (nums.length === 0) return 0;
    return nums.reduce((sum, n) => sum + n, 0) / nums.length;
  }
}

