exercises.solution:
class Account {
  constructor(owner, initialBalance) {
    this.owner = owner;
    this._balance = initialBalance >= 0 ? initialBalance : 0;
  }

  deposit(amount) {
    if (amount > 0) this._balance += amount;
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this._balance) this._balance -= amount;
  }

  get balance() {
    return this._balance;
  }
}

class SavingsAccount extends Account {
  constructor(owner, initialBalance, interestRate) {
    super(owner, initialBalance);
    this.interestRate = interestRate;
  }

  applyInterest() {
    this._balance += this._balance * this.interestRate;
  }

  get projectedBalance() {
    return this._balance * (1 + this.interestRate);
  }
}

