exercises.solution:
class Book {
  constructor(title, author) {
    this.title = title;
    this.author = author;
    this.isAvailable = true;
  }
}

class Library {
  constructor(name) {
    this.name = name;
    this._books = [];
  }

  add(book) {
    this._books.push(book);
  }

  checkout(title) {
    const book = this._books.find(b => b.title === title && b.isAvailable);
    if (book) {
      book.isAvailable = false;
      return true;
    }
    return false;
  }

  returnBook(title) {
    const book = this._books.find(b => b.title === title && !b.isAvailable);
    if (book) {
      book.isAvailable = true;
      return true;
    }
    return false;
  }

  get available() {
    return this._books.filter(b => b.isAvailable).map(b => b.title);
  }
}

