exercises.solution:
class Inventory {
  constructor() {
    this._items = [];
  }

  add(item) {
    this._items.push(item);
  }

  remove(name) {
    const idx = this._items.findIndex(i => i.name === name);
    if (idx !== -1) this._items.splice(idx, 1);
  }

  has(name) {
    return this._items.some(i => i.name === name);
  }

  get items() {
    return this._items.map(i => ({ name: i.name, weight: i.weight }));
  }

  get totalWeight() {
    return this._items.reduce((sum, i) => sum + i.weight, 0);
  }
}

class Player {
  constructor(name, maxWeight) {
    this.name = name;
    this.maxWeight = maxWeight;
    this.inventory = new Inventory();
  }

  pickup(item) {
    if (this.inventory.totalWeight + item.weight <= this.maxWeight) {
      this.inventory.add(item);
      return true;
    }
    return false;
  }

  drop(name) {
    if (this.inventory.has(name)) {
      this.inventory.remove(name);
      return true;
    }
    return false;
  }
}

