exercises.solution:
function safeJsonParse(jsonString) {
  const result = { data: null, error: null, attempted: false };
  try {
    result.data = JSON.parse(jsonString);
  } catch (error) {
    result.error = error.message;
  } finally {
    result.attempted = true;
  }
  return result;
}

