exercises.solution:
class ConfigError extends Error {
  constructor(key, reason) {
    super("Config error [" + key + "]: " + reason);
    this.name = "ConfigError";
    this.key = key;
  }
}

function loadConfig(jsonString) {
  let parsed;
  try {
    parsed = JSON.parse(jsonString);
  } catch (error) {
    return { success: false, config: null, errors: ["Invalid JSON: " + error.message] };
  }

  const errors = [];

  if (typeof parsed.host !== "string" || parsed.host.trim() === "") {
    errors.push(new ConfigError("host", "must be a non-empty string"));
  }

  if (typeof parsed.port !== "number" || parsed.port < 1 || parsed.port > 65535) {
    errors.push(new ConfigError("port", "must be a number between 1 and 65535"));
  }

  if (errors.length > 0) {
    return { success: false, config: null, errors: errors.map(e => e.message) };
  }

  return { success: true, config: { host: parsed.host, port: parsed.port }, errors: [] };
}

