exercises.solution:
async function collectResults(promises) {
  const values = [];
  const errors = [];
  for (let i = 0; i < promises.length; i++) {
    try {
      const val = await promises[i];
      values.push(val);
    } catch (err) {
      errors.push(err.message);
    }
  }
  return { values: values, errors: errors };
}

