exercises.solution:
function buildSearchIndex(docs) {
  return docs.reduce(function(index, doc) {
    const words = doc.body.toLowerCase().split(/\s+/).filter(function(w) { return w.length > 0; });
    words.forEach(function(word) {
      if (!index[word]) {
        index[word] = [];
      }
      if (index[word].indexOf(doc.title) === -1) {
        index[word].push(doc.title);
      }
    });
    return index;
  }, {});
}

