exercises.solution:
function tournamentRankings(players, minGames) {
  return players
    .filter(function(p) { return (p.wins + p.losses) >= minGames; })
    .map(function(p) {
      return { player: p.player, winRate: p.wins / (p.wins + p.losses) * 100 };
    })
    .sort(function(a, b) { return b.winRate - a.winRate; })
    .map(function(p, i) {
      return "#" + (i + 1) + " " + p.player + " (" + (Math.round(p.winRate * 10) / 10) + "%)";
    });
}

