/**
 * @param {*} initialValue - The value to validate
 * @returns {object} A validator object with chainable rule methods:
 *   .required() - value must not be undefined, null, or ""
 *   .minLength(n) - string length must be >= n
 *   .maxLength(n) - string length must be <= n
 *   .matches(regex) - value must match the regex pattern
 *   .validate() - returns { valid: boolean, errors: string[] }
 */
function createValidator(initialValue) {

}

exercises.solution:
function createValidator(initialValue) {
  const rules = [];
  const validator = {
    required: function() {
      rules.push(function(val) {
        if (val === undefined || val === null || val === "") return "Value is required";
        return null;
      });
      return validator;
    },
    minLength: function(n) {
      rules.push(function(val) {
        if (typeof val === "string" && val.length < n) return "Must be at least " + n + " characters";
        return null;
      });
      return validator;
    },
    maxLength: function(n) {
      rules.push(function(val) {
        if (typeof val === "string" && val.length > n) return "Must be at most " + n + " characters";
        return null;
      });
      return validator;
    },
    matches: function(regex) {
      rules.push(function(val) {
        if (typeof val === "string" && !regex.test(val)) return "Must match pattern " + regex;
        return null;
      });
      return validator;
    },
    validate: function() {
      const errors = rules
        .map(function(rule) { return rule(initialValue); })
        .filter(function(err) { return err !== null; });
      return { valid: errors.length === 0, errors: errors };
    }
  };
  return validator;
}

