/**
 * @param {Object[]} data - Array of objects (all objects have the same keys)
 * @param {string} containerId - The id of the container element to append the table to
 * Creates a <table> with <thead> (one <th> per key) and <tbody> (one <tr> per object, one <td> per value)
 */
