/**
 * @param {Function} asyncFn - An async function (takes no arguments) that may resolve or reject
 * @param {number} maxRetries - Maximum number of retry attempts (not counting the initial try)
 * @returns {Promise<*>} The resolved value on success
 * @throws {Error} The last error if all attempts fail, with message "Failed after N attempts: <original message>"
 */
async function retry(asyncFn, maxRetries) {

}

exercises.solution:
async function retry(asyncFn, maxRetries) {
  let lastError;
  for (let i = 0; i <= maxRetries; i++) {
    try {
      return await asyncFn();
    } catch (err) {
      lastError = err;
    }
  }
  throw new Error("Failed after " + (maxRetries + 1) + " attempts: " + lastError.message);
}

