async function fetchWithTimeout(asyncFns, timeoutMs) {
  const dataPromise = Promise.all(asyncFns.map(function(fn) { return fn(); }));
  const timeoutPromise = new Promise(function(_, reject) {
    setTimeout(function() {
      reject(new Error("Timeout after " + timeoutMs + "ms"));
