function createTabs(tabData, containerId) {
  var container = document.getElementById(containerId);
  var tabBar = document.createElement("div");
  tabBar.className = "tab-bar";
  var contentArea = document.createElement("div");
  contentArea.className = "tab-content";

  var buttons = [];
  var panels = [];

  tabData.forEach(function(tab, index) {
    var button = document.createElement("button");
    button.textContent = tab.label;
    button.className = index === 0 ? "tab-button active" : "tab-button";
    buttons.push(button);
    tabBar.appendChild(button);

    var panel = document.createElement("div");
    panel.textContent = tab.content;
    panel.className = index === 0 ? "tab-panel" : "tab-panel hidden";
    panels.push(panel);
    contentArea.appendChild(panel);

    button.addEventListener("click", function() {
      for (var i = 0; i < buttons.length; i++) {
        buttons[i].classList.remove("active");
        panels[i].classList.add("hidden");
      }
      button.classList.add("active");
      panel.classList.remove("hidden");
    });
  });

  container.appendChild(tabBar);
  container.appendChild(contentArea);
}

