function setupFormValidation(formId, rules) {
  var form = document.getElementById(formId);
  var fields = Object.keys(rules);
  for (var i = 0; i < fields.length; i++) {
    (function(fieldName) {
      var rule = rules[fieldName];
      var input = form.querySelector('[name="' + fieldName + '"]');
      if (!input) return;
      var errorEl = document.createElement("span");
      errorEl.className = "error-message";
      input.parentNode.insertBefore(errorEl, input.nextSibling);

      input.addEventListener("input", function() {
        var value = input.value;
        var error = "";
        if (rule.required && value.trim() === "") {
          error = "Required";
        } else if (rule.minLength && value.length < rule.minLength && value.trim() !== "") {
          error = "Min " + rule.minLength + " characters";
        } else if (rule.maxLength && value.length > rule.maxLength) {
          error = "Max " + rule.maxLength + " characters";
        }
        errorEl.textContent = error;
        if (error) {
          input.classList.add("invalid");
          input.classList.remove("valid");
        } else {
          input.classList.add("valid");
          input.classList.remove("invalid");
        }
      });
    })(fields[i]);
  }
}

