function parseKeyValue(str) {
  var result = {};
  var pairs = str.split(";");
  for (var i = 0; i < pairs.length; i++) {
    var trimmed = pairs[i].trim();
    if (!trimmed) continue;
    var match = trimmed.match(/^\s*(\w+)\s*=\s*"([^"]*)"\s*$/) || trimmed.match(/^\s*(\w+)\s*=\s*(\w*)\s*$/);
    if (match) {
      result[match[1]] = match[2];
    }
  }
  return result;
}

