function extractTags(html) {
  var regex = /<([a-zA-Z][a-zA-Z0-9]*)(?:\s[^>]*)?\/?>/g;
  var match;
  var seen = {};
  var result = [];
  while ((match = regex.exec(html)) !== null) {
    var tag = match[1].toLowerCase();
    if (!seen[tag]) {
      seen[tag] = true;
      result.push(tag);
    }
  }
  return result;
}

