exercises.solution:
function render(template, data) {
  return template.replace(/\{\{\s*([^}]+?)\s*\}\}/g, function(match, key) {
    var parts = key.split(".");
    var value = data;
    for (var i = 0; i < parts.length; i++) {
      if (value === undefined || value === null) return "";
      value = value[parts[i]];
    }
    return value !== undefined && value !== null ? String(value) : "";
  });
}

