function analyzeStudents(students) {
  var groups = {};
  students.forEach(function(s) {
    if (!groups[s.grade]) groups[s.grade] = [];
    groups[s.grade].push(s);
  });
  return Object.keys(groups).sort().map(function(grade) {
    var grp = groups[grade];
    var totalAvg = grp.reduce(function(sum, s) {
      var courseAvg = s.courses.reduce(function(s2, c) { return s2 + c.score; }, 0) / s.courses.length;
      return sum + courseAvg;
    }, 0) / grp.length;
    return { grade: grade, count: grp.length, avgScore: Math.round(totalAvg * 100) / 100 };
  });
}

