exercises.solution:
function pivot(records, rowKey, colKey, valueKey) {
  var cols = [];
  var seen = {};
  records.forEach(function(r) {
    if (!seen[r[colKey]]) { cols.push(r[colKey]); seen[r[colKey]] = true; }
  });
  cols.sort();
  var rows = {};
  records.forEach(function(r) {
    var rk = r[rowKey];
    if (!rows[rk]) {
      rows[rk] = { _row: rk };
      cols.forEach(function(c) { rows[rk][c] = 0; });
    }
    rows[rk][r[colKey]] += r[valueKey];
  });
  return Object.keys(rows).sort().map(function(k) { return rows[k]; });
}

