class LinkedList {
  constructor() {
    this.head = null;
  }
  append(value) {
    var node = { value: value, next: null };
    if (!this.head) {
      this.head = node;
      return;
    }
    var current = this.head;
    while (current.next) {
      current = current.next;
    }
    current.next = node;
  }
  prepend(value) {
    var node = { value: value, next: this.head };
    this.head = node;
  }
  size() {
    var count = 0;
    var current = this.head;
    while (current) {
      count++;
      current = current.next;
    }
    return count;
  }
  toArray() {
    var arr = [];
    var current = this.head;
    while (current) {
      arr.push(current.value);
      current = current.next;
    }
    return arr;
  }
  find(value) {
    var current = this.head;
    while (current) {
      if (current.value === value) return current;
      current = current.next;
    }
    return null;
  }
  removeAt(index) {
    if (index < 0 || !this.head) return undefined;
    if (index === 0) {
      var val = this.head.value;
      this.head = this.head.next;
      return val;
    }
    var current = this.head;
    for (var i = 0; i < index - 1; i++) {
      if (!current.next) return undefined;
      current = current.next;
    }
    if (!current.next) return undefined;
    var val = current.next.value;
    current.next = current.next.next;
    return val;
  }
}

