class Graph {
  constructor() {
    this.adjacencyList = {};
  }
  addVertex(vertex) {
    if (!this.adjacencyList[vertex]) {
      this.adjacencyList[vertex] = [];
    }
  }
  addEdge(v1, v2) {
    if (!this.adjacencyList[v1] || !this.adjacencyList[v2]) return;
    if (this.adjacencyList[v1].indexOf(v2) === -1) {
      this.adjacencyList[v1].push(v2);
    }
    if (this.adjacencyList[v2].indexOf(v1) === -1) {
      this.adjacencyList[v2].push(v1);
    }
  }
  getNeighbors(vertex) {
    return this.adjacencyList[vertex] || [];
  }
  hasVertex(vertex) {
    return !!this.adjacencyList[vertex];
  }
  hasEdge(v1, v2) {
    if (!this.adjacencyList[v1]) return false;
    return this.adjacencyList[v1].indexOf(v2) !== -1;
  }
  bfs(start) {
    if (!this.adjacencyList[start]) return [];
    var visited = {};
    var queue = [start];
    var result = [];
    visited[start] = true;
    while (queue.length > 0) {
      var vertex = queue.shift();
      result.push(vertex);
      var neighbors = this.adjacencyList[vertex];
      for (var i = 0; i < neighbors.length; i++) {
        if (!visited[neighbors[i]]) {
          visited[neighbors[i]] = true;
          queue.push(neighbors[i]);
        }
      }
    }
    return result;
  }
  dfs(start) {
    if (!this.adjacencyList[start]) return [];
    var visited = {};
    var result = [];
    var self = this;
    function traverse(vertex) {
      visited[vertex] = true;
      result.push(vertex);
      var neighbors = self.adjacencyList[vertex];
      for (var i = 0; i < neighbors.length; i++) {
        if (!visited[neighbors[i]]) {
          traverse(neighbors[i]);
        }
      }
    }
    traverse(start);
    return result;
  }
}

