exercises.solution:
function insertionSort(arr) {
  var result = arr.slice();
  for (var i = 1; i < result.length; i++) {
    var current = result[i];
    var j = i - 1;
    while (j >= 0 && result[j] > current) {
      result[j + 1] = result[j];
      j--;
    }
    result[j + 1] = current;
  }
  return result;
}

