exercises.solution:
function quickSort(arr) {
  if (arr.length <= 1) return arr.slice();
  var pivot = arr[0];
  var less = [];
  var greater = [];
  for (var i = 1; i < arr.length; i++) {
    if (arr[i] < pivot) {
      less.push(arr[i]);
    } else {
      greater.push(arr[i]);
    }
  }
  return quickSort(less).concat([pivot], quickSort(greater));
}

